const ACCENT =
  'M14915 6181 c-26 -11 -582 -334 -611 -355 -12 -9 -31 -35 -43 -59 -20 -40 -21 -60 -21 -293 0 -232 1 -251 20 -282 23 -38 81 -66 119 -59 14 3 112 56 216 118 105 62 218 128 252 148 122 71 198 119 215 138 40 44 48 96 48 322 0 236 -5 263 -61 304 -30 22 -103 31 -134 18z';
const FLIP = 'translate(0 715) scale(.1 -.1)';

// Centre lines of the letters, in the 2000-wide space of the 1.1x scaled group below. They only
// drive the writing reveal as a mask, so they may overshoot the glyphs.
const STROKES: { d: string[]; delay: number }[] = [
  { d: ['M113 490V165L415 480V160'], delay: 0 },
  { d: ['M525 255L650 450', 'M770 255L580 575'], delay: 0.3 },
  {
    d: ['M843 230V510', 'M843 330A87 87 0 0 1 1018 330V510', 'M1018 330A87 87 0 0 1 1193 330V510'],
    delay: 0.55,
  },
  { d: ['M1330 235V510'], delay: 0.85 },
  { d: ['M1445 510V235', 'M1445 380C1445 300 1490 250 1570 250'], delay: 1.0 },
  { d: ['M1771 245A117 115 0 1 0 1771 475A117 115 0 1 0 1771 245Z', 'M1888 230V510'], delay: 1.2 },
];

export function Wordmark({ animated = false }: { animated?: boolean }) {
  const id = useId();
  const mask = `nm-wm-mask-${id.replace(/:/g, '')}`;
  return (
    <svg
      className={`nm-wordmark nm-wm ${animated ? 'nm-wm-live' : ''}`}
      viewBox="0 0 2200 715"
      aria-hidden="true"
    >
      {animated && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="2200" height="715">
          <g
            transform="scale(1.1)"
            fill="none"
            stroke="#fff"
            strokeWidth="130"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            {STROKES.flatMap((l, i) =>
              l.d.map((d, j) => (
                <path
                  key={`${i}-${j}`}
                  d={d}
                  pathLength={1}
                  style={{ animationDelay: `${l.delay + j * 0.08}s` }}
                />
              )),
            )}
          </g>
        </mask>
      )}
      <g fill="currentColor">
        <g mask={animated ? `url(#${mask})` : undefined}>
          <path d={LETTERS} transform={FLIP} />
        </g>
        <g className="nm-wm-hop">
          <g className="nm-wm-drop">
            <path d={ACCENT} transform={FLIP} />
          </g>
        </g>
      </g>
    </svg>
  );
}
